def book(x, y, w, h, c):
    return [R(x, y, w, h, c), R(x + 4, y + 4, w - 8, h - 8, CR), R(x, y, 6, h, c)]


def tree_bare(c=BR):
    return [R(166, 80, 8, 80, c)] + polyline([(170, 100), (140, 70), (130, 50)], 4, c) + polyline([(170, 90), (200, 64), (214, 56)], 4, c) + [line(150, 80, 160, 60, 3, c)]


